INSERT INTO tb_game (title, score, game_year, genre, platforms, img_url, short_description, long_description) VALUES ('Mass Effect Trilogy', 4.8, 2012, 'Role-playing (RPG), Shooter', 'XBox, Playstation, PC', 'https://raw.githubusercontent.com/devsuperior/java-spring-dslist/main/resources/1.png', 'Uma jornada épica pelo espaço onde suas escolhas moldam o destino da galáxia contra os Reapers.', 'A trilogia Mass Effect coloca você no papel do Comandante Shepard, liderando uma equipe de especialistas em uma missão para salvar a galáxia. O jogo é famoso por seu sistema de escolhas morais que impactam drasticamente o desenrolar da narrativa e o destino de civilizações inteiras.');
INSERT INTO tb_game (title, score, game_year, genre, platforms, img_url, short_description, long_description) VALUES ('Red Dead Redemption 2', 4.7, 2018, 'Role-playing (RPG), Adventure', 'XBox, Playstation, PC', 'https://raw.githubusercontent.com/devsuperior/java-spring-dslist/main/resources/2.png', 'A saga de Arthur Morgan e a gangue Van der Linde no coração de uma América em transformação.', 'Ambientado em 1899, o jogo segue o fora-da-lei Arthur Morgan enquanto ele lida com o declínio do Velho Oeste. Com um mundo aberto incrivelmente detalhado, o título oferece uma experiência imersiva sobre lealdade, redenção e o preço da liberdade em um mundo que não aceita mais bandidos.');
INSERT INTO tb_game (title, score, game_year, genre, platforms, img_url, short_description, long_description) VALUES ('The Witcher 3: Wild Hunt', 4.7, 2014, 'Role-playing (RPG), Adventure', 'XBox, Playstation, PC', 'https://raw.githubusercontent.com/devsuperior/java-spring-dslist/main/resources/3.png', 'Geralt de Rívia busca sua filha adotiva em um mundo devastado por monstros e tramas políticas.', 'No papel de um caçador de monstros profissional, você explora o Continente em busca de Ciri. O jogo é um marco do RPG ocidental, apresentando missões secundárias profundas, um sistema de combate tático e um mundo rico baseado na mitologia eslava.');
INSERT INTO tb_game (title, score, game_year, genre, platforms, img_url, short_description, long_description) VALUES ('Sekiro: Shadows Die Twice', 3.8, 2019, 'Role-playing (RPG), Adventure', 'XBox, Playstation, PC', 'https://raw.githubusercontent.com/devsuperior/java-spring-dslist/main/resources/4.png', 'Um shinobi embarca em uma jornada de vingança e resgate no perigoso período Sengoku no Japão.', 'Diferente de Dark Souls, Sekiro foca em furtividade e combate de precisão com espadas. Você controla o Lobo de um Braço Só, um guerreiro desonrado que deve enfrentar samurais e criaturas místicas para recuperar seu mestre sequestrado.');
INSERT INTO tb_game (title, score, game_year, genre, platforms, img_url, short_description, long_description) VALUES ('Ghost of Tsushima', 4.6, 2012, 'Role-playing (RPG), Adventure', 'XBox, Playstation, PC', 'https://raw.githubusercontent.com/devsuperior/java-spring-dslist/main/resources/5.png', 'O samurai Jin Sakai luta para libertar a ilha de Tsushima da invasão mongol no século XIII.', 'Jin deve escolher entre seguir o rígido código samurai ou adotar táticas de "Fantasma" para vencer um exército numericamente superior. O jogo destaca-se pelo seu estilo visual cinematográfico inspirado nos filmes de Akira Kurosawa.');
INSERT INTO tb_game (title, score, game_year, genre, platforms, img_url, short_description, long_description) VALUES ('Super Mario World', 4.7, 1990, 'Platform', 'Super Ness, PC', 'https://raw.githubusercontent.com/devsuperior/java-spring-dslist/main/resources/6.png', 'A aventura definitiva de Mario e Yoshi para salvar a Princesa Peach das garras de Bowser.', 'Um dos maiores clássicos de plataforma de todos os tempos. Explore');
